// ======================================================
// AI RESUME SCREENING - HR EMAIL FORMATTER
// FULL FIXED VERSION
// ======================================================


// ======================================================
// 1. GET DATA FROM THE CORRECT NODES
// ======================================================

// Current incoming item
// This will normally be coming from the Google Sheets node
const inputItem = $input.item;

const currentData = inputItem?.json || {};


// ------------------------------------------------------
// IMPORTANT:
// Get the ORIGINAL AI screening result directly
// from the AI Agent node.
// ------------------------------------------------------

const aiItem = $('AI Agent').first();

const aiJson = aiItem?.json || {};


// AI Agent usually returns:
// {
//   output: {
//      candidate_name: "...",
//      overall_score: 85,
//      ...
//   }
// }
//
// But sometimes "output" may be a JSON string.
// This code supports both formats.

let result = aiJson.output ?? aiJson;


// ------------------------------------------------------
// If AI output is a JSON string, convert it to an object
// ------------------------------------------------------

if (typeof result === 'string') {

  try {

    // Remove possible markdown code fences
    let cleaned = result
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    result = JSON.parse(cleaned);

  } catch (error) {

    console.log(
      'Could not parse AI output as JSON:',
      error.message
    );

    result = {};
  }
}


// Make absolutely sure result is an object
if (
  !result ||
  typeof result !== 'object' ||
  Array.isArray(result)
) {
  result = {};
}


// ======================================================
// 2. GET ORIGINAL FORM DATA
// ======================================================

const formItem = $('On form submission').first();

const formData = formItem?.json || {};


// Preserve uploaded resume binary
const binary =
  formItem?.binary ||
  inputItem?.binary ||
  {};


// ======================================================
// 3. HELPER FUNCTIONS
// ======================================================


// Safe fallback for missing values
function safe(value, fallback = 'Not provided') {

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return fallback;
  }

  return value;
}


// Convert values into arrays safely
function normalizeArray(value) {

  if (Array.isArray(value)) {
    return value
      .filter(item =>
        item !== undefined &&
        item !== null &&
        String(item).trim() !== ''
      )
      .map(item => String(item).trim());
  }

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return [];
  }

  // Support stringified JSON arrays
  if (typeof value === 'string') {

    const trimmed = value.trim();

    if (
      trimmed.startsWith('[') &&
      trimmed.endsWith(']')
    ) {

      try {

        const parsed = JSON.parse(trimmed);

        if (Array.isArray(parsed)) {
          return parsed
            .filter(Boolean)
            .map(item => String(item).trim());
        }

      } catch (error) {
        // Continue below
      }
    }

    return [trimmed];
  }

  return [String(value)];
}


// Escape dynamic AI-generated text
// before placing it inside HTML
function escapeHtml(value) {

  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}


// ======================================================
// 4. CANDIDATE INFORMATION
// ======================================================

const candidateName = safe(
  result.candidate_name,
  'Candidate'
);


// Score
let score = Number(result.overall_score);

if (!Number.isFinite(score)) {
  score = 0;
}


// Keep score between 0 and 100
score = Math.min(
  Math.max(Math.round(score), 0),
  100
);


// Decision
const decision = String(
  safe(
    result.decision,
    score >= 80
      ? 'SHORTLIST'
      : score >= 65
        ? 'REVIEW'
        : 'REJECT'
  )
).toUpperCase();


// Skills
const matchedSkills = normalizeArray(
  result.matched_skills
);

const missingSkills = normalizeArray(
  result.missing_skills
);


// Strengths / concerns
const strengths = normalizeArray(
  result.strengths
);

const concerns = normalizeArray(
  result.concerns
);


// Experience
const experienceMatch = safe(
  result.experience_match,
  'Not provided'
);


// Recruiter summary
const recruiterSummary = safe(
  result.recruiter_summary,
  'No recruiter summary was generated.'
);


// ======================================================
// 5. JOB INFORMATION
// ======================================================

// Your form field is called "job_description",
// so get the selected role directly from the form.

const jobTitle = safe(
  formData.job_description,
  currentData.job_title ||
  currentData.jobTitle ||
  'AI Automation Engineer'
);


// ======================================================
// 6. SCORE DESIGN
// ======================================================

let scoreLabel = 'Low Match';

let scoreColor = '#dc2626';

let scoreBackground = '#fef2f2';

let scoreBorder = '#fecaca';


if (score >= 80) {

  scoreLabel = 'Strong Match';

  scoreColor = '#15803d';

  scoreBackground = '#ecfdf5';

  scoreBorder = '#bbf7d0';

}
else if (score >= 65) {

  scoreLabel = 'Potential Match';

  scoreColor = '#b45309';

  scoreBackground = '#fffbeb';

  scoreBorder = '#fde68a';

}


// ======================================================
// 7. MATCHED SKILLS HTML
// ======================================================

const matchedSkillHTML = matchedSkills.length

  ? matchedSkills
      .map(skill => `

        <span style="
          display:inline-block;
          background:#E8F5E9;
          color:#1B5E20;
          border-radius:20px;
          padding:7px 12px;
          margin:4px 4px 4px 0;
          font-size:13px;
          font-weight:600;
        ">
          ✓ ${escapeHtml(skill)}
        </span>

      `)
      .join('')

  : `
      <span style="color:#777;">
        No matched skills identified
      </span>
    `;


// ======================================================
// 8. MISSING SKILLS HTML
// ======================================================

const missingSkillHTML = missingSkills.length

  ? missingSkills
      .map(skill => `

        <span style="
          display:inline-block;
          background:#FFF3E0;
          color:#E65100;
          border-radius:20px;
          padding:7px 12px;
          margin:4px 4px 4px 0;
          font-size:13px;
          font-weight:600;
        ">
          ${escapeHtml(skill)}
        </span>

      `)
      .join('')

  : `
      <span style="color:#777;">
        No significant skill gaps identified
      </span>
    `;


// ======================================================
// 9. STRENGTHS HTML
// ======================================================

const strengthsHTML = strengths.length

  ? strengths
      .map(strength => `

        <li style="margin-bottom:7px;">
          ${escapeHtml(strength)}
        </li>

      `)
      .join('')

  : `
      <li>
        No specific strengths provided.
      </li>
    `;


// ======================================================
// 10. CONCERNS HTML
// ======================================================

const concernsHTML = concerns.length

  ? concerns
      .map(concern => `

        <li style="margin-bottom:7px;">
          ${escapeHtml(concern)}
        </li>

      `)
      .join('')

  : `
      <li>
        No major concerns identified.
      </li>
    `;


// ======================================================
// 11. EMAIL HTML
// ======================================================

const emailHtml = `

<!DOCTYPE html>

<html>

<head>

<meta charset="UTF-8">

<meta
  name="viewport"
  content="width=device-width, initial-scale=1.0"
>

</head>


<body style="
  margin:0;
  padding:0;
  background:#f4f7fb;
  font-family:Arial,Helvetica,sans-serif;
  color:#172033;
">


<table
  width="100%"
  cellpadding="0"
  cellspacing="0"
  border="0"
  style="
    background:#f4f7fb;
    padding:30px 10px;
  "
>


<tr>

<td align="center">


<table
  width="680"
  cellpadding="0"
  cellspacing="0"
  border="0"
  style="
    max-width:680px;
    width:100%;
    background:#ffffff;
    border-radius:16px;
    overflow:hidden;
    box-shadow:0 5px 25px rgba(0,0,0,0.08);
  "
>


<!-- ================================================= -->
<!-- HEADER -->
<!-- ================================================= -->


<tr>

<td style="
  padding:32px;
  background:linear-gradient(
    135deg,
    #172554,
    #2563eb
  );
  color:white;
">


<div style="
  font-size:13px;
  letter-spacing:1.5px;
  text-transform:uppercase;
  opacity:.85;
">

AI RECRUITMENT ASSISTANT

</div>


<h1 style="
  margin:8px 0 5px;
  font-size:28px;
">

Candidate Shortlisted 🎯

</h1>


<p style="
  margin:0;
  font-size:15px;
  opacity:.9;
">

AI-powered resume screening report

</p>


</td>

</tr>


<!-- ================================================= -->
<!-- CANDIDATE -->
<!-- ================================================= -->


<tr>

<td style="
  padding:30px 32px 10px;
">


<table
  width="100%"
  cellpadding="0"
  cellspacing="0"
  border="0"
>


<tr>


<td valign="top">


<div style="
  font-size:12px;
  color:#64748b;
  text-transform:uppercase;
  letter-spacing:.8px;
">

Candidate

</div>


<div style="
  font-size:24px;
  font-weight:bold;
  margin-top:5px;
">

${escapeHtml(candidateName)}

</div>


<div style="
  margin-top:5px;
  color:#64748b;
  font-size:14px;
">

Applied for:
<strong>
${escapeHtml(jobTitle)}
</strong>

</div>


</td>


<td
  align="right"
  valign="top"
>


<div style="
  display:inline-block;
  background:${scoreBackground};
  border:1px solid ${scoreBorder};
  border-radius:12px;
  padding:12px 18px;
">


<div style="
  font-size:30px;
  font-weight:bold;
  color:${scoreColor};
">

${score}%

</div>


<div style="
  font-size:12px;
  color:${scoreColor};
  font-weight:bold;
">

${scoreLabel}

</div>


</div>


</td>


</tr>

</table>


</td>

</tr>


<!-- ================================================= -->
<!-- SCORE BAR -->
<!-- ================================================= -->


<tr>

<td style="
  padding:10px 32px 25px;
">


<div style="
  height:10px;
  background:#e5e7eb;
  border-radius:10px;
  overflow:hidden;
">


<div style="
  width:${score}%;
  height:10px;
  background:${scoreColor};
  border-radius:10px;
">

</div>


</div>


</td>

</tr>


<!-- ================================================= -->
<!-- RECRUITER SUMMARY -->
<!-- ================================================= -->


<tr>

<td style="
  padding:0 32px 25px;
">


<div style="
  background:#f8fafc;
  border-left:4px solid #2563eb;
  border-radius:8px;
  padding:18px;
">


