  color:#2563eb;
  margin-bottom:8px;
">

RECRUITER SUMMARY

</div>


<div style="
  font-size:14px;
  line-height:1.6;
  color:#334155;
">

${escapeHtml(recruiterSummary)}

</div>


</div>


</td>

</tr>


<!-- ================================================= -->
<!-- EXPERIENCE MATCH -->
<!-- ================================================= -->


<tr>

<td style="
  padding:0 32px 25px;
">


<h3 style="
  margin:0 0 12px;
  font-size:17px;
">

Experience Match

</h3>


<div style="
  padding:14px;
  background:#f8fafc;
