<!-- ================================================= -->


<tr>

<td style="
  padding:0 32px 25px;
">


<table
  width="100%"
  cellpadding="0"
  cellspacing="0"
  border="0"
>


<tr>


<td
  width="48%"
  valign="top"
  style="
    background:#f0fdf4;
    border-radius:10px;
