</div>


<ul style="
  padding-left:18px;
  margin:0;
  color:#334155;
  font-size:13px;
  line-height:1.5;
">

${concernsHTML}

</ul>


</td>


</tr>

</table>


</td>

</tr>


<!-- ================================================= -->
<!-- RESUME -->
<!-- ================================================= -->


<tr>

<td
  align="center"
  style="
    padding:10px 32px 35px;
  "
>


