`;


// ======================================================
// 12. EMAIL SUBJECT
// ======================================================

const emailSubject =
  `🎯 Candidate Shortlisted — ${candidateName} | ${jobTitle}`;


// ======================================================
// 13. DEBUG INFORMATION
// ======================================================

// These values are also returned so that you can
// easily inspect the node output in n8n.

const debugData = {

  ai_result_found:
    Object.keys(result).length > 0,

  candidate_name:
    candidateName,

  overall_score:
    score,

  decision:
    decision,

  matched_skills_count:
    matchedSkills.length,

  missing_skills_count:
    missingSkills.length,

  strengths_count:
    strengths.length,

  concerns_count:
    concerns.length,

  job_title:
    jobTitle

};


// ======================================================
// 14. RETURN DATA
// ======================================================

return {

  json: {

    ...currentData,

    // Original structured AI result
    screening_result: result,

    // Email fields
    hr_email_subject: emailSubject,

    hr_email_html: emailHtml,

    // Useful individual fields
    candidate_name: candidateName,

    candidate_score: score,

    candidate_decision: decision,

    matched_skills: matchedSkills,

    missing_skills: missingSkills,

    experience_match: experienceMatch,

    strengths: strengths,

    concerns: concerns,

    recruiter_summary: recruiterSummary,

    job_title: jobTitle,

    // Helpful while testing
    debug: debugData

  },


  // Keep the uploaded resume
  binary: binary

};
